<template><div class="page"><h2 class="page-title">导入微信账单</h2><p class="muted">账单只在本机解析；当前支持微信 .xlsx，支付宝和银行卡将在后续版本开放。</p>
<div class="card section"><el-upload drag :auto-upload="false" :limit="1" accept=".xlsx" :on-change="f=>selected=f.raw"><p>拖入或选择微信账单</p><small>原文件仅临时解析，导入完成后删除</small></el-upload><el-button class="section" type="primary" :loading="uploading" :disabled="!selected" @click="upload">开始导入</el-button>
<template v-if="report"><div class="result-banner section"><div><span class="eyebrow">导入结果</span><h3>已新增 {{report.inserted_rows}} 笔，跳过 {{report.duplicate_rows}} 笔重复记录</h3><p>失败 {{report.failed_rows}} 笔，需留意 {{report.warning_rows}} 条提示。</p></div><el-button type="primary" @click="$router.push('/analytics')">查看消费分析</el-button></div><h3 class="section">数据质量</h3><el-descriptions border :column="4"><el-descriptions-item label="有效记录">{{report.total_rows}}</el-descriptions-item><el-descriptions-item label="消费">{{report.flow_type_counts?.consumption||0}}</el-descriptions-item><el-descriptions-item label="退款">{{report.refund_rows}}</el-descriptions-item><el-descriptions-item label="转账（不计消费）">{{report.transfer_rows}}</el-descriptions-item><el-descriptions-item label="其他业务类型">{{report.unknown_flow_rows}}</el-descriptions-item><el-descriptions-item label="待确认消费（笔数）">{{formatRatio(report.uncategorized_consumption_ratio)}}</el-descriptions-item><el-descriptions-item label="待确认消费（金额）">{{formatRatio(report.uncategorized_consumption_amount_ratio)}}</el-descriptions-item><el-descriptions-item label="账单范围">{{localDate(report.earliest_transaction_time)}} 至 {{localDate(report.latest_transaction_time)}}</el-descriptions-item></el-descriptions><el-alert class="section" type="info" :closable="false" title="待确认消费不影响总消费；如需更精细的分类预算，可在下方进行可选审核。"/></template></div>
<div class="card section"><h3>导入历史</h3><el-table :data="imports" empty-text="尚未导入账单"><el-table-column label="导入时间"><template #default="s">{{localDate(s.row.started_at)}}</template></el-table-column><el-table-column prop="source" label="来源"/><el-table-column label="结果"><template #default="s">{{statusName(s.row.status)}}</template></el-table-column><el-table-column prop="inserted_rows" label="新增"/><el-table-column prop="duplicate_rows" label="重复"/><el-table-column prop="failed_rows" label="失败"/></el-table></div>
<div class="card section"><div class="actions"><div style="flex:1"><h3>可选：完善“其他 / 待确认消费”分类</h3><p class="muted">不影响查看总消费；仅在你希望提高分类预算精度时处理。</p></div><el-button v-if="deepseek?.ready" :loading="aiLoading" @click="requestSuggestions('A')">辅助分析优先确认组</el-button><el-button v-if="deepseek?.ready" :loading="aiLoading" @click="requestSuggestions('B')">辅助分析建议确认组</el-button></div><el-alert v-if="reviewSummary" :title="`当前待确认：${reviewSummary.current_other_count}笔（${formatRatio(reviewSummary.current_other_count_ratio)}），${formatMoney(reviewSummary.current_other_amount_minor)}（${formatRatio(reviewSummary.current_other_amount_ratio)}）`" type="info" :closable="false"/><el-alert class="section" :type="deepseek?.ready?'warning':'info'" :closable="false" :title="deepseek?.ready?'AI辅助已就绪；发送前会再次征得同意':'AI辅助未配置，仍可使用规则和人工确认'"/><p class="muted">优先确认、建议确认、可暂时保留只表示审核顺序，不代表消费重要性或是否应该削减。AI只给候选，不会自动改标签；个人二维码默认不发送。</p>
<el-table :data="reviews" empty-text="当前没有可审核组；重新选择原账单可生成，重复交易不会入库"><el-table-column label="审核建议" width="110"><template #default="s">{{tierName(s.row.tier)}}</template></el-table-column><el-table-column prop="merchant_hint" label="商户短文本" min-width="180"/><el-table-column prop="dominant_time_bucket" label="常见时段"/><el-table-column prop="transaction_count" label="笔数"/><el-table-column label="金额"><template #default="s">{{formatMoney(s.row.amount_minor)}}</template></el-table-column><el-table-column label="AI候选" min-width="190"><template #default="s"><template v-if="s.row.model_suggestion"><el-tag>{{categoryName(s.row.model_suggestion.category_code)}} {{s.row.model_suggestion.confidence.toFixed(0)}}%</el-tag><div class="compact-actions" v-if="s.row.model_suggestion.category_code!=='other'"><el-button size="small" type="primary" @click="acceptSuggestion(s.row.model_suggestion)">接受</el-button><el-button size="small" @click="rejectSuggestion(s.row.model_suggestion)">拒绝</el-button></div></template><span v-else class="muted">未分析</span></template></el-table-column><el-table-column label="由我确认" min-width="150"><template #default="s"><el-select placeholder="选择类别" @change="v=>confirmReview(s.row,v)"><el-option v-for="c in categories.filter(x=>x.code!=='other')" :key="c.code" :label="c.name" :value="c.code"/></el-select></template></el-table-column></el-table></div>
<el-collapse class="section"><el-collapse-item title="查看标准交易记录（用于核对）" name="transactions"><div class="actions"><el-button @click="load">刷新</el-button></div><el-table :data="transactions"><el-table-column label="时间"><template #default="s">{{localDate(s.row.occurred_at)}}</template></el-table-column><el-table-column label="金额"><template #default="s">{{formatMoney(s.row.amount_minor)}}</template></el-table-column><el-table-column prop="flow_type" label="类型"/><el-table-column label="分类"><template #default="s"><el-select :model-value="s.row.effective_category" @change="v=>changeCategory(s.row,v)"><el-option v-for="c in categories" :key="c.code" :label="c.name" :value="c.code"/></el-select></template></el-table-column></el-table></el-collapse-item></el-collapse></div></template>
<script setup>
import { onMounted,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { api } from '../api/client.js';import { formatMoney } from '../utils/money.js';import { localDate } from '../utils/display.js'
const selected=ref(),uploading=ref(false),aiLoading=ref(false),report=ref(),transactions=ref([]),categories=ref([]),imports=ref([]),reviews=ref([]),reviewSummary=ref(),deepseek=ref();const formatRatio=value=>`${((value||0)*100).toFixed(1)}%`;const tierName=v=>({A:'优先确认',B:'建议确认',C:'可暂时保留'}[v]||v);const statusName=v=>({completed:'导入完成',completed_with_warnings:'已导入，有提示',duplicate_file:'已导入过'}[v]||v)
async function load(){try{const [t,c,i,r,d]=await Promise.all([api.get('/transactions?page_size=100'),api.get('/categories'),api.get('/imports'),api.get('/categories/review'),api.get('/classification/providers/deepseek')]);transactions.value=t.items;categories.value=c.items;imports.value=i.items;reviews.value=r.items;reviewSummary.value=r.summary;deepseek.value=d}catch(e){ElMessage.error(e.message)}}
async function upload(){const body=new FormData();body.append('file',selected.value);uploading.value=true;try{report.value=await api.post('/imports/wechat',body,{timeout:120000});ElMessage.success('账单导入完成');await load()}catch(e){ElMessage.error(e.message);if(e.code==='REQUEST_TIMEOUT')await load()}finally{uploading.value=false}}
async function changeCategory(row,code){try{await api.patch(`/transactions/${row.id}/category`,{category_code:code});row.effective_category=code;ElMessage.success('分类已确认')}catch(e){ElMessage.error(e.message)}}
async function confirmReview(row,code){try{const r=await api.patch(`/transactions/${row.representative_transaction_id}/category`,{category_code:code});ElMessage.success(`已应用到同组 ${r.updated_transactions} 笔交易`);await load()}catch(e){ElMessage.error(e.message)}}
const categoryName=code=>categories.value.find(x=>x.code===code)?.name||code
async function requestSuggestions(tier){try{await ElMessageBox.confirm(`将发送最多${tier==='A'?10:20}个商户组的脱敏短文本、金额区间、时段和频次区间。个人二维码会跳过。是否继续？`,'隐私确认',{type:'warning',confirmButtonText:'同意并分析',cancelButtonText:'取消'});aiLoading.value=true;const r=await api.post('/categories/review/deepseek-suggestions',{tier,limit:tier==='A'?10:20},{timeout:120000});ElMessage.success(`生成 ${r.created} 个候选，跳过 ${r.skipped_private} 个隐私或证据不足组`);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'已取消')}finally{aiLoading.value=false}}
async function acceptSuggestion(item){try{const r=await api.post(`/categories/suggestions/${item.id}/accept`);ElMessage.success(`已应用到同组 ${r.updated_transactions} 笔交易`);await load()}catch(e){ElMessage.error(e.message)}}async function rejectSuggestion(item){try{await api.post(`/categories/suggestions/${item.id}/reject`);ElMessage.success('已拒绝该建议');await load()}catch(e){ElMessage.error(e.message)}}onMounted(load)
</script>
